use xiom.io;
fn generate_sequence(length: Int) -> Vec[Int] {
  var seq: Vec[Int] = Vec[Int].new();
  var seed = 42;
  var i = 0;
  while i < length {
    seed = (seed * 1103515245 + 12345) % 2147483648;
    seq.push(1 + (seed % 9));
    i += 1;
  };
  seq
}

fn compare_sequences(a: &Vec[Int], b: &Vec[Int]) -> Bool {
  if a.len() != b.len() { return false; };
  var i = 0;
  while i < a.len() {
    if a.get(i).unwrap() != b.get(i).unwrap() { return false; };
    i += 1;
  };
  true
}

fn main() -> Int {
  let target = generate_sequence(5);
  var player: Vec[Int] = Vec[Int].new();
  var i = 0;
  while i < target.len() {
    player.push(target.get(i).unwrap());
    i += 1;
  };
  io.println((compare_sequences(&target, &player)).to_str());
  return 0;
}
